/**
 * Dead-grass blade texture (own work, generated by code; design section 5, requirement 6.4).
 * Pure data: no three import. `Grass.tsx` wraps the result in a DataTexture.
 *
 * Layout: RGBA, 128 x 128, row 0 is the BOTTOM of the card (v = 0, flipY off). Blades
 * grow upward from row 0. Alpha is 0 or 255 only, so alphaTest = 0.5 gives crisp edges.
 */
import { mulberry32 } from '../../../engine/rng';

export const GRASS_TEXTURE_SIZE = 128;
const BLADES = 22;

/** Dead-grass palette (sRGB): straw, dry tan, grey-brown. */
const PALETTE: readonly (readonly [number, number, number])[] = [
  [122, 108, 66],
  [98, 86, 54],
  [138, 124, 84],
  [84, 74, 52],
];

export function grassTexture(seed: number): Uint8Array {
  const size = GRASS_TEXTURE_SIZE;
  const data = new Uint8Array(size * size * 4);
  const rand = mulberry32(seed);

  // Transparent texels carry a base colour so mip levels do not bleed black into blades.
  const base = PALETTE[0] as readonly [number, number, number];
  for (let i = 0; i < size * size; i++) {
    data[i * 4] = base[0];
    data[i * 4 + 1] = base[1];
    data[i * 4 + 2] = base[2];
    data[i * 4 + 3] = 0;
  }

  for (let b = 0; b < BLADES; b++) {
    const x0 = 4 + rand() * (size - 8);
    const length = size * (0.45 + rand() * 0.5);
    const lean = (rand() - 0.5) * 0.9; // total sideways drift, in fractions of the length
    const bend = (rand() - 0.5) * 0.5; // curvature
    const halfW0 = 1.2 + rand() * 1.6;
    const [r, g, bl] = PALETTE[Math.floor(rand() * PALETTE.length)] as readonly [
      number,
      number,
      number,
    ];
    const shade = 0.8 + rand() * 0.3;

    for (let y = 0; y < length; y++) {
      const t = y / length;
      const cx = x0 + length * (lean * t + bend * t * t);
      const halfW = Math.max(0.3, halfW0 * (1 - t));
      const xa = Math.max(0, Math.floor(cx - halfW));
      const xb = Math.min(size - 1, Math.ceil(cx + halfW));
      const row = Math.min(size - 1, y);
      for (let x = xa; x <= xb; x++) {
        if (Math.abs(x + 0.5 - cx) > halfW) continue;
        const o = (row * size + x) * 4;
        data[o] = Math.min(255, Math.round(r * shade));
        data[o + 1] = Math.min(255, Math.round(g * shade));
        data[o + 2] = Math.min(255, Math.round(bl * shade));
        data[o + 3] = 255;
      }
    }
  }
  return data;
}
